/** @addtogroup EnumValue_peripherals
  * @{
  */



/* =========================================================================================================================== */
/* ================                                            SPI                                            ================ */
/* =========================================================================================================================== */

/* ==========================================================  CR  =========================================================== */
/* ==================================================  SPI CR SPEN [0..0]  =================================================== */
typedef enum {                                  /*!< SPI_CR_SPEN                                                               */
  SPI_CR_SPEN_Disable                  = 0,     /*!< Disable : SPI is disabled                                                 */
  SPI_CR_SPEN_Enable                   = 1,     /*!< Enable : SPI is enabled                                                   */
} SPI_CR_SPEN_Enum;

/* ==================================================  SPI CR MSTR [1..1]  =================================================== */
typedef enum {                                  /*!< SPI_CR_MSTR                                                               */
  SPI_CR_MSTR_Master_Mode              = 1,     /*!< Master_Mode : Select master mode                                          */
  SPI_CR_MSTR_Slave_Mode               = 0,     /*!< Slave_Mode : Select slave mode                                            */
} SPI_CR_MSTR_Enum;

/* ==================================================  SPI CR CPHA [2..2]  =================================================== */
typedef enum {                                  /*!< SPI_CR_CPHA                                                               */
  SPI_CR_CPHA_Change_Mode              = 1,     /*!< Change_Mode : Data is changed on the leading edge of SPCK and
                                                                    captured on the following edge                             */
  SPI_CR_CPHA_Capture_Mode             = 0,     /*!< Capture_Mode : Data is captured on the leading edge of SPCK
                                                     and changed on the following edge                                         */
} SPI_CR_CPHA_Enum;

/* ==================================================  SPI CR CPOL [3..3]  =================================================== */
typedef enum {                                  /*!< SPI_CR_CPOL                                                               */
  SPI_CR_CPOL_Low                      = 0,     /*!< Low : The inactive state value of SPCK is logic level Low                 */
  SPI_CR_CPOL_High                     = 1,     /*!< High : The inactive state value of SPCK is logic level High               */
} SPI_CR_CPOL_Enum;

